SELECT UPPER(SUBSTR(name, 1, 1)) AS initial, COUNT(*) AS customers
FROM customers
GROUP BY UPPER(SUBSTR(name, 1, 1));

SELECT t.value AS tag, COUNT(DISTINCT e.user_id) AS users
FROM events e, json_each(e.payload, '$.tags') t
